{
  "sql": "SELECT ut.license_id, s.system_name, s.vendor, l.department, ut.credit_consumed, ut.credit_limit, ROUND(ut.credit_consumed / ut.credit_limit * 100, 1) as utilization_pct, ut.flagged_queries, l.total_seats, l.assigned_seats, l.active_seats, (l.assigned_seats - l.active_seats) as reclaimable_seats, ROUND((l.assigned_seats - l.active_seats) * l.cost_per_seat, 2) as reclaimable_cost FROM usage_tracking ut JOIN licenses l ON ut.license_id = l.license_id JOIN ai_systems s ON l.system_id = s.system_id WHERE ut.month = (SELECT MAX(month) FROM usage_tracking) AND (ut.credit_consumed / ut.credit_limit > 0.85 OR ut.flagged_queries > 5 OR (l.assigned_seats - l.active_seats) > l.total_seats * 0.15) ORDER BY utilization_pct DESC"
}

parameters.jsCode:
const rows = $input.first()?.json?.rows || [];

if (rows.length === 0) {
  return [{ json: { has_alerts: false } }];
}

const overBudget = rows.filter(r => r.utilization_pct > 85);
const flaggedQueries = rows.filter(r => r.flagged_queries > 5);
const reclaimable = rows.filter(r => r.reclaimable_seats > 0);

let alerts = [];
let totalSavings = 0;

for (const r of overBudget) {
  alerts.push({
    type: 'OVER_BUDGET',
    severity: r.utilization_pct > 95 ? 'critical' : 'warning',
    system: r.system_name,
    department: r.department,
    message: `${r.system_name} (${r.department}): ${r.utilization_pct}% of credit limit consumed ($${r.credit_consumed.toLocaleString()} / $${r.credit_limit.toLocaleString()})`
  });
}

for (const r of flaggedQueries) {
  alerts.push({
    type: 'FLAGGED_QUERIES',
    severity: 'warning',
    system: r.system_name,
    department: r.department,
    message: `${r.system_name}: ${r.flagged_queries} flagged queries detected (possible restricted data access)`
  });
}

for (const r of reclaimable) {
  totalSavings += r.reclaimable_cost;
  alerts.push({
    type: 'RECLAIMABLE',
    severity: 'info',
    system: r.system_name,
    department: r.department,
    message: `${r.system_name}: ${r.reclaimable_seats} unused seats reclaimable (saving $${r.reclaimable_cost.toLocaleString()}/month)`
  });
}

const criticals = alerts.filter(a => a.severity === 'critical');
const warnings = alerts.filter(a => a.severity === 'warning');
const infos = alerts.filter(a => a.severity === 'info');

let report = '# Budget & License Governance Alert\n\n';
if (criticals.length) report += '## CRITICAL\n' + criticals.map(a => `- ${a.message}`).join('\n') + '\n\n';
if (warnings.length) report += '## WARNING\n' + warnings.map(a => `- ${a.message}`).join('\n') + '\n\n';
if (infos.length) report += `## SAVINGS OPPORTUNITY ($${totalSavings.toLocaleString()}/month)\n` + infos.map(a => `- ${a.message}`).join('\n') + '\n\n';

return [{
  json: {
    has_alerts: alerts.length > 0,
    alert_count: alerts.length,
    critical_count: criticals.length,
    total_monthly_savings: totalSavings,
    report: report,
    alerts: alerts
  }
}];
